urlset:
{%- set reply_shell_url = get_url(path="reply-shell", trailing_slash=true) %}
{%- for sitemap_entry in entries %}
{%- if sitemap_entry.permalink != reply_shell_url %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- endif %}

{%- endif %}
{%- endfor %}
